    || level_mode == 3)
    completion_segment =
        (SubSegment*)(base + LEVEL_LAST_SEGMENT_BASE);
else
    completion_segment = (SubSegment*)(
        base + SCRATCH_SEGMENT_SLOTS_BASE + sizeof(SubSegment));
active_segment = (char*)completion_segment;

if (level_mode == 0
    || level_mode == 4
    || level_mode == 1
    || level_mode == 7) {
    active_segment = base + LEVEL_LAST_SEGMENT_BASE;
